create unique index if not exists uq_gateway_token_link_active on public.gateway_payment_token_links(user_id,instrument_id,gateway_id) where status='active'; create unique index if not exists uq_gateway_token_link_provider_fingerprint on public.gateway_payment_token_links(user_id,provider,token_fingerprint) where status='active'; alter table public.gateway_payment_instruments add constraint gateway_payment_instruments_last4_format check (last4 is null or last4 ~ '^[0-9]{4}$'); alter table public.gateway_payment_instruments add constraint gateway_payment_instruments_brand_length check (brand is null or length(brand) between 1 and 32);